package com.companion.agent;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.companion.common.exception.BusinessException;import com.companion.common.result.ResultCode;import com.companion.config.AgentProperties;import com.companion.dto.request.AgentRunCreateRequest;import com.companion.entity.AgentRun;import com.companion.entity.enums.AgentRunStatus;import com.companion.mapper.AgentRunMapper;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Propagation;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;
@Service public class AgentRunCreationService {private final AgentRunMapper mapper;private final AgentProperties properties;public AgentRunCreationService(AgentRunMapper m,AgentProperties p){mapper=m;properties=p;}
 @Transactional(propagation=Propagation.REQUIRES_NEW) public AgentRun create(Long u,AgentRunCreateRequest q){
  if(u==null||q==null||q.getRequestId()==null||q.getRequestId().isBlank()||q.getRequestId().trim().length()>64||q.getGoal()==null||q.getGoal().isBlank()||q.getGoal().trim().length()>4000)throw new BusinessException(ResultCode.PARAM_ERROR.getCode(),"Invalid Agent run input");
  String requestId=q.getRequestId().trim(),goal=q.getGoal().trim();int max=q.getMaxSteps()==null?properties.getDefaultMaxSteps():q.getMaxSteps();if(max<1||max>properties.getMaxStepsLimit())throw new BusinessException(ResultCode.PARAM_ERROR.getCode(),"maxSteps exceeds configured limit");AgentRun existing=find(u,requestId);if(existing!=null)return same(existing,goal,max);LocalDateTime now=LocalDateTime.now();AgentRun r=new AgentRun();r.setUserId(u);r.setRequestId(requestId);r.setGoal(goal);r.setStatus(AgentRunStatus.PENDING.name());r.setCurrentStep(0);r.setMaxSteps(max);r.setVersion(0);r.setExecutionVersion(0);r.setCreateTime(now);r.setUpdateTime(now);try{mapper.insert(r);return r;}catch(DuplicateKeyException e){return same(find(u,requestId),goal,max);}}
 private AgentRun find(Long u,String id){return mapper.selectOne(new QueryWrapper<AgentRun>().eq("user_id",u).eq("request_id",id));}private AgentRun same(AgentRun r,String goal,int max){if(r==null)throw new IllegalStateException("Idempotent Agent Run missing");if(!goal.equals(r.getGoal())||max!=r.getMaxSteps())throw new BusinessException(409,"requestId already used with different Agent input");return r;}
}
